import{_ as t,o as s,c as a,a7 as i}from"./chunks/framework.C4ZIv4ii.js";const p=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/performance.md","filePath":"guide/performance.md","lastUpdated":1791310829000}'),n={name:"guide/performance.md"};function o(r,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>Every speed setting lives under <strong>Customizer → Performance</strong>. Each one is off by default, so a site changes only when you switch something on. Most of them work on the finished page, which means they apply to any theme and to pages built with the builder alike.</p><h2 id="recommended-setup" tabindex="-1">Recommended setup <a class="header-anchor" href="#recommended-setup" aria-label="Permalink to &quot;Recommended setup&quot;">​</a></h2><p>For a site on the default Falcon theme, switch on:</p><ol><li><strong>Static Caching</strong></li><li><strong>Compiled CSS</strong> and then <strong>Critical CSS</strong></li><li><strong>Lazy-load Images</strong></li><li><strong>Inline Only the Icons in Use</strong></li><li><strong>Host Google Fonts Locally</strong></li><li><strong>Defer JavaScript</strong>, <strong>Minify HTML</strong> and <strong>Minify CSS</strong></li></ol><p>Then check the site in a private window, and run <a href="https://pagespeed.web.dev/" target="_blank" rel="noreferrer">PageSpeed Insights</a> on the mobile tab, which is the stricter test.</p><h2 id="the-settings" tabindex="-1">The settings <a class="header-anchor" href="#the-settings" aria-label="Permalink to &quot;The settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Themes</th></tr></thead><tbody><tr><td><strong>Static Caching</strong></td><td>Saves each finished page and serves the copy to the next visitor. Pages that hold something personal (a cart, an account) are never cached.</td><td>Any</td></tr><tr><td><strong>Lazy-load Images</strong></td><td>Images further down the page load only when the reader scrolls to them. The first three images stay eager, and the first image after the site header (usually the hero) is fetched first.</td><td>Any</td></tr><tr><td><strong>Defer JavaScript</strong></td><td>Scripts load without stopping the page from drawing. Scripts that have to run first (Tailwind, Alpine, the security check) are left alone.</td><td>Any</td></tr><tr><td><strong>Minify HTML / Minify CSS</strong></td><td>Removes the blank space between tags and inside style blocks.</td><td>Any</td></tr><tr><td><strong>Load Assets Only When Needed</strong></td><td>Font Awesome, Alpine.js and SweetAlert load only on pages that use them.</td><td>Falcon theme</td></tr><tr><td><strong>Compiled CSS</strong></td><td>One pre-built stylesheet (~65 KB) instead of building styles in the browser with the 400 KB Tailwind script.</td><td>Falcon theme</td></tr><tr><td><strong>Critical CSS</strong></td><td>With Compiled CSS on, each page carries, inline, only the styles it uses (typically 10–20 KB). The full stylesheet loads without holding up the first paint, so styles added later by JavaScript still apply.</td><td>Falcon theme</td></tr><tr><td><strong>Inline Only the Icons in Use</strong></td><td>Icon libraries (Font Awesome, Bootstrap Icons, Remix, Boxicons, Lucide) are 70–140 KB stylesheets each. With this on, the page carries only the rules for the icons it shows, usually a kilobyte or two, and drops the libraries it doesn&#39;t use.</td><td>Any</td></tr><tr><td><strong>Host Google Fonts Locally</strong></td><td>Copies the Google Fonts the site uses to <code>public/falcon-fonts</code> and serves them from your own server, with their rules inline. Visitors&#39; browsers never contact Google, which also helps with the GDPR.</td><td>Any</td></tr><tr><td><strong>WebP Conversion, Image Quality, Max Image Width</strong></td><td>Applied to images when they&#39;re uploaded.</td><td>Any</td></tr></tbody></table><h3 id="inline-only-the-icons-in-use" tabindex="-1">Inline Only the Icons in Use <a class="header-anchor" href="#inline-only-the-icons-in-use" aria-label="Permalink to &quot;Inline Only the Icons in Use&quot;">​</a></h3><p>The whole page is scanned for icon names, including Alpine bindings and inline scripts, so an icon a widget swaps in on click is kept too. The one case it can&#39;t see is a theme that adds icons from its <strong>own JavaScript files</strong>. If icons go missing on such a theme, switch the option off, or add this to the theme&#39;s <code>functions.php</code> to keep linking the full stylesheets:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add_falcon_filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;falcon_icon_inline_css&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () =&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="host-google-fonts-locally" tabindex="-1">Host Google Fonts Locally <a class="header-anchor" href="#host-google-fonts-locally" aria-label="Permalink to &quot;Host Google Fonts Locally&quot;">​</a></h3><p>The copy is made in the background, after a page&#39;s first visit, so no visitor waits for it. Until the copy exists, and whenever a download fails, the page keeps loading the fonts from Google as before; a failed download is retried an hour later. Pages served in the meantime are not kept in the page cache. When you change fonts in the Customizer, the new ones are copied the same way.</p><h3 id="critical-css" tabindex="-1">Critical CSS <a class="header-anchor" href="#critical-css" aria-label="Permalink to &quot;Critical CSS&quot;">​</a></h3><p>The stylesheet still downloads in full, after the page has shown, so nothing that relies on it is lost. A browser with JavaScript turned off gets the normal stylesheet link.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><ul><li>Images from the media library carry their width and height, so the page keeps their space while they load and the text below doesn&#39;t jump.</li><li>If an image element has no alt text of its own, the alt text from the media library is used. Give your logo an alt text in the library: a linked logo without one is an unnamed link to screen readers and to PageSpeed.</li><li>Upload images close to the size they&#39;re shown at. A logo shown at 180 px doesn&#39;t need a 1,600 px file.</li></ul><h2 id="things-outside-the-cms" tabindex="-1">Things outside the CMS <a class="header-anchor" href="#things-outside-the-cms" aria-label="Permalink to &quot;Things outside the CMS&quot;">​</a></h2><ul><li><strong>Compression:</strong> the server (or a CDN such as Cloudflare) should gzip or brotli the HTML. Without compression a page can be several times larger on the wire.</li><li><strong>Cache lifetimes for static files:</strong> configure them in the web server or CDN, so returning visitors don&#39;t download unchanged CSS, fonts and images again.</li><li><strong>PHP limits and OPcache:</strong> see <strong>Settings → Site Health</strong>, which checks these for you.</li></ul>',19)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
